cd "/mnt/c/Projects/asset allocation/asset-allocation" && python3 - <<'EOF'
import yaml
from decimal import Decimal
with open("data/external/entity_jims_trust_full_local.yaml") as f:
    data = yaml.safe_load(f)
by_class = {}
for s in data["segments"]:
    if s["segment"] != "investable":
        continue
    pc = s["policy_class"]
    by_class.setdefault(pc, {})[s.get("liquidity_tier") or "untiered"] = Decimal(s["amount_usd"])
for pc, tiers in by_class.items():
    total = sum(tiers.values())
    if total == 0:
        print(pc, "total: $0.00 (no exposure)")
        continue
    print(pc, "total:", total)
    for t, amt in tiers.items():
        print(f"   {t}: {amt/total*100:.1f}%")
EOF
